<template>
<button class="btn btn-primary"
data-bs-toggle="modal"
data-bs-target="#grn-clearence"
>open</button>
                   <div class="modal fade mymodal" id="grn-clearence" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">GRN SHORTAGE STATEMENT CLEARENCE FORM {{ props.Item }}</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-clearence-form" ></button>
      </div>
<div class="modal-body" >
          <div class="mt-4">
           <form @submit.prevent="submitGrnClearence()">
            <div class="input-group">
                           <input type="text" placeholder="Enter Confirmation remark" class="form-control me-2" v-model="description">
                           <button class="btn btn-primary" :disabled="loading">
                           <span v-if="loading" v-html="loadingSpinner()"></span>
                           <span v-else> Confirm and Clear</span>
                          </button>
            </div>
           </form>

          </div>
      </div>

            <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>
      </div>

    </div>
  </div>

</div>


        <!-- <div class="layout-px-spacing bg-white"> 

        </div> -->





</template>

<script setup>
    import { onMounted, ref,inject,watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Work Order' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });


const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    GrnItemId: String,
    GrnId : String,
    Item : String
});

const loadingSpinner = inject('loadingSpinner')

const loading = ref(false)




const showError = inject('showError')
const showMessage = inject('showMessage')
const clearForm = ()=>{
  description.value = ''
  document.getElementById('close-clearence-form').click()
}


const description = ref('')
const submitGrnClearence = async()=>{
  loading.value = true
  const payload = {
     description : description.value,
     item_id : props.GrnItemId,
     grn_id : props.GrnId,
     issuer_id : JSON.parse(localStorage.getItem('user')).id
  }
  try{
      const response = await axiosInstance.post('grn-clearence',payload)
      showMessage('Item Confirmed and Cleared!')
      clearForm()
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    loading.value = false;
  }

}


    onMounted(async() => {

    });
</script>

